"use client";

import { forwardRef, type ButtonHTMLAttributes } from "react";

export type SwitchProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, "onChange"> & { checked: boolean; onCheckedChange?: (checked: boolean) => void };
export const Switch = forwardRef<HTMLButtonElement, SwitchProps>(({ checked, onCheckedChange, className = "", disabled, ...props }, ref) => (
  <button ref={ref} type="button" role="switch" aria-checked={checked} disabled={disabled} onClick={() => onCheckedChange?.(!checked)} className={`co-relative co-inline-flex co-h-6 co-w-11 co-shrink-0 co-cursor-pointer co-items-center co-rounded-full co-border-2 co-border-transparent co-transition co-outline-none focus-visible:co-ring-2 focus-visible:co-ring-black disabled:co-cursor-not-allowed disabled:co-opacity-50 ${checked ? "co-bg-black" : "co-bg-black/20"} ${className}`.trim()} {...props}>
    <span aria-hidden="true" className={`co-pointer-events-none co-block co-size-5 co-rounded-full co-bg-white co-shadow-sm co-transition ${checked ? "co-translate-x-5" : "co-translate-x-0"}`} />
  </button>
));
Switch.displayName = "Switch";
